//! The media formats each Version Profile's TVs play, from Samsung's TV media
//! specifications (`data/media.toml`, generated by `data/media-specs.py`).
//! The Shims raise the `media-format-unsupported` Diagnostic when the App
//! tries one of them and the Engine can't play it (see shims/src/media.ts).

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::sync::OnceLock;

/// What one TV year's specifications list.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TvMedia {
    pub profile: String,
    pub year: u32,
    /// The specification page, under developer.samsung.com/smarttv/develop/.
    pub page: String,
    #[serde(rename(deserialize = "model_groups"))]
    pub model_groups: Vec<String>,
    #[serde(rename(deserialize = "format"))]
    pub formats: Vec<MediaFormat>,
    /// A codec only some model groups list, with those groups.
    #[serde(default, rename(deserialize = "some_models"))]
    pub some_models: BTreeMap<String, Vec<String>>,
}

/// Containers, and the codecs the TVs play in each of them.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MediaFormat {
    pub containers: Vec<String>,
    pub codecs: Vec<String>,
    /// From the Music table rather than the video tables.
    #[serde(default)]
    pub music: bool,
}

#[derive(Debug, Deserialize)]
pub struct MediaCatalog {
    tv: Vec<TvMedia>,
}

impl MediaCatalog {
    pub fn parse(toml: &str) -> Result<MediaCatalog, toml::de::Error> {
        toml::from_str(toml)
    }

    /// The catalog bundled with the simulator.
    pub fn bundled() -> &'static MediaCatalog {
        static CATALOG: OnceLock<MediaCatalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            MediaCatalog::parse(include_str!("../data/media.toml"))
                .expect("bundled media.toml is valid")
        })
    }

    /// What Tizen `version`'s TVs play, if their specifications are known.
    pub fn for_version(&self, version: &str) -> Option<&TvMedia> {
        self.tv.iter().find(|tv| tv.profile == version)
    }
}

impl TvMedia {
    /// Whether every model group plays `codec` in `container`; `None` when no
    /// model of the year does.
    pub fn plays(&self, container: &str, codec: &str) -> Option<Models<'_>> {
        let listed = self.formats.iter().any(|format| {
            format.containers.iter().any(|c| c == container)
                && format.codecs.iter().any(|c| c == codec)
        });
        if !listed {
            return None;
        }
        Some(match self.some_models.get(codec) {
            Some(groups) => Models::Some(groups),
            None => Models::All,
        })
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum Models<'a> {
    All,
    Some(&'a [String]),
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::profile::VersionProfile;

    fn tv(version: &str) -> &'static TvMedia {
        MediaCatalog::bundled().for_version(version).unwrap()
    }

    #[test]
    fn every_version_profile_has_its_years_specifications() {
        for profile in VersionProfile::all() {
            assert!(
                MediaCatalog::bundled()
                    .for_version(&profile.version)
                    .is_some(),
                "no media specifications for Tizen {}",
                profile.version
            );
        }
    }

    // The values below are read off each year's page by hand.

    #[test]
    fn every_year_plays_h264_and_aac_in_mp4_on_every_model() {
        for profile in VersionProfile::all() {
            let tv = tv(&profile.version);
            assert_eq!(tv.plays("MP4", "H.264"), Some(Models::All), "{}", tv.year);
            assert_eq!(tv.plays("MP4", "AAC"), Some(Models::All), "{}", tv.year);
        }
    }

    #[test]
    fn the_2024_tvs_play_ac3_in_mpeg_ts_and_wma_only_on_some_models() {
        let tv = tv("8.0");
        assert_eq!(tv.year, 2024);
        assert_eq!(tv.plays("MPEG-TS", "AC-3"), Some(Models::All));
        assert_eq!(tv.plays("MP4", "E-AC-3"), Some(Models::All));
        assert_eq!(tv.plays("MP4", "HEVC"), Some(Models::All));
        let Some(Models::Some(groups)) = tv.plays("WMA", "WMA") else {
            panic!("WMA should be on some 2024 models only");
        };
        assert_eq!(groups.len(), 10);
        assert!(!groups.iter().any(|g| g.starts_with("24TV_BASIC4")));
    }

    #[test]
    fn fhd_models_of_2017_to_2020_lack_vp9() {
        let Some(Models::Some(groups)) = tv("3.0").plays("WebM", "VP9") else {
            panic!("VP9 should be on some 2017 models only");
        };
        assert!(!groups.iter().any(|g| g.contains("FHD")), "{groups:?}");
        assert_eq!(tv("6.0").plays("WebM", "VP9"), Some(Models::All));
    }

    #[test]
    fn formats_a_year_does_not_list_are_not_played() {
        assert_eq!(tv("9.0").plays("WMA", "WMA"), None);
        assert_eq!(tv("3.0").plays("MP4", "AV1"), None);
        assert_eq!(tv("3.0").plays("MP4", "Opus"), None);
        assert_eq!(tv("4.0").plays("MP4", "Opus"), Some(Models::All));
    }
}
